#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>
#define NC 768
#define NL 12
#define NH 12
#define NV 50257
#define NF 3072
#define D 64
#define LSZ 7087872
typedef struct{char**k;int*v;int n;}Map;
Map voc,mrg;
float*W,*wte,*wpe,*lnfg,*lnfb;
char*idstr[NV];
int cp2b[512];
char*bstr[256];
int toks[4100],nt;
Map mk(int n){Map m;m.n=n;m.k=calloc(n,sizeof(char*));m.v=malloc(n*4);return m;}
unsigned H(char*s){unsigned h=2166136261u;while(*s)h=(h^(unsigned char)*s++)*16777619u;return h;}
void put(Map*m,char*s,int v){unsigned i=H(s)&(m->n-1);while(m->k[i]){if(!strcmp(m->k[i],s))return;i=(i+1)&(m->n-1);}m->k[i]=s;m->v[i]=v;}
int get(Map*m,char*s){unsigned i=H(s)&(m->n-1);while(m->k[i]){if(!strcmp(m->k[i],s))return m->v[i];i=(i+1)&(m->n-1);}return -1;}
void bytes_init(){
 int used[256]={0},cp[256],b,r,id,n=0,oi=0,order[256];
 int lo[3]={33,161,174},hi[3]={126,172,255};
 for(r=0;r<3;r++)for(b=lo[r];b<=hi[r];b++){used[b]=1;cp[b]=b;}
 for(b=0;b<256;b++)if(!used[b]){cp[b]=256+n;n++;}
 for(r=0;r<3;r++)for(b=lo[r];b<=hi[r];b++)order[oi++]=b;
 for(b=0;b<256;b++)if(!used[b])order[oi++]=b;
 for(id=0;id<256;id++){b=order[id];int c=cp[b];char*s=malloc(4);int L=0;
  if(c<128)s[L++]=c;else{s[L++]=0xC0|(c>>6);s[L++]=0x80|(c&63);}s[L]=0;
  bstr[b]=s;cp2b[c]=b;put(&voc,s,id);idstr[id]=s;}
}
void bpe_init(char*fn){
 FILE*f=fopen(fn,"r");char line[512];fgets(line,512,f);int rank=0;
 while(fgets(line,512,f)){char*sp=strchr(line,' ');if(!sp)continue;
  char*nl=strchr(line,'\n');if(nl)*nl=0;*sp=0;char*L=line,*R=sp+1;
  int a=strlen(L),b=strlen(R);
  char*comb=malloc(a+b+1);memcpy(comb,L,a);memcpy(comb+a,R,b);comb[a+b]=0;
  int id=256+rank;put(&voc,comb,id);idstr[id]=comb;
  char*key=malloc(a+b+2);memcpy(key,L,a);key[a]='\n';memcpy(key+a+1,R,b);key[a+b+1]=0;
  put(&mrg,key,rank);rank++;}
 fclose(f);char*e="<|endoftext|>";put(&voc,e,50256);idstr[50256]=e;
}
int bpe_encode(char*txt,int len,int*out){
 char*sym[2048];int ns=0,i;char key[512],buf[512];
 for(i=0;i<len;i++)sym[ns++]=strdup(bstr[(unsigned char)txt[i]]);
 while(1){int best=1<<30,bi=-1;
  for(i=0;i+1<ns;i++){snprintf(key,512,"%s\n%s",sym[i],sym[i+1]);int r=get(&mrg,key);if(r>=0&&r<best){best=r;bi=i;}}
  if(bi<0)break;
  snprintf(buf,512,"%s%s",sym[bi],sym[bi+1]);free(sym[bi]);free(sym[bi+1]);sym[bi]=strdup(buf);
  for(i=bi+1;i+1<ns;i++)sym[i]=sym[i+1];ns--;}
 int c=0;for(i=0;i<ns;i++){out[c++]=get(&voc,sym[i]);free(sym[i]);}return c;
}
void emit(char*s,int a,int b){if(b<=a)return;int ids[2048];int c=bpe_encode(s+a,b-a,ids);for(int k=0;k<c;k++)toks[nt++]=ids[k];}
int iS(int c){return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\v'||c=='\f';}
void pretok(char*s){
 int n=strlen(s),i=0;
 while(i<n){unsigned char c=s[i];
  if(c=='\''&&i+1<n){char a=s[i+1],d=i+2<n?s[i+2]:0;int L=0;
   if(a=='s'||a=='t'||a=='m'||a=='d')L=2;
   else if((a=='r'&&d=='e')||(a=='v'&&d=='e')||(a=='l'&&d=='l'))L=3;
   if(L){emit(s,i,i+L);i+=L;continue;}}
  int k=i+(c==' '?1:0),j;
  if(k<n&&isalpha((unsigned char)s[k])){j=k;while(j<n&&isalpha((unsigned char)s[j]))j++;emit(s,i,j);i=j;continue;}
  if(k<n&&isdigit((unsigned char)s[k])){j=k;while(j<n&&isdigit((unsigned char)s[j]))j++;emit(s,i,j);i=j;continue;}
  if(k<n&&!iS((unsigned char)s[k])&&!isalpha((unsigned char)s[k])&&!isdigit((unsigned char)s[k])){j=k;while(j<n&&!iS((unsigned char)s[j])&&!isalpha((unsigned char)s[j])&&!isdigit((unsigned char)s[j]))j++;emit(s,i,j);i=j;continue;}
  if(iS(c)){j=i;while(j<n&&iS((unsigned char)s[j]))j++;if(j<n)j--;if(j<=i)j=i+1;emit(s,i,j);i=j;continue;}
  i++;}
}
float*Lb(int l){return wpe+1024*NC+(size_t)l*LSZ;}
void ln(float*x,float*o,int T,float*g,float*b){
 for(int t=0;t<T;t++){float*xr=x+t*NC,*ou=o+t*NC,m=0,v=0;int c;
  for(c=0;c<NC;c++)m+=xr[c];m/=NC;
  for(c=0;c<NC;c++){float d=xr[c]-m;v+=d*d;}v/=NC;
  float is=1/sqrtf(v+1e-5f);
  for(c=0;c<NC;c++)ou[c]=(xr[c]-m)*is*g[c]+b[c];}
}
float gelu(float x){return 0.5f*x*(1+tanhf(0.7978845608f*(x+0.044715f*x*x*x)));}
int forward(int T){
 float*x=malloc(T*NC*4),*a=malloc(T*NC*4),*qkv=malloc(T*2304*4),*ao=malloc(T*NC*4),*hh=malloc((size_t)T*NF*4);
 int t,c,l,h,j,d,fo;
 for(t=0;t<T;t++)for(c=0;c<NC;c++)x[t*NC+c]=wte[(size_t)toks[t]*NC+c]+wpe[t*NC+c];
 for(l=0;l<NL;l++){float*b=Lb(l);
  float*g1=b,*b1=b+768,*aw=b+1536,*ab=b+1771008,*cw=b+1773312,*cb=b+2363136,*g2=b+2363904,*b2=b+2364672,*fcw=b+2365440,*fcb=b+4724736,*pw=b+4727808,*pb=b+7087104;
  ln(x,a,T,g1,b1);
  for(t=0;t<T;t++)for(fo=0;fo<2304;fo++){float s=ab[fo],*ar=a+t*NC;for(c=0;c<NC;c++)s+=ar[c]*aw[c*2304+fo];qkv[t*2304+fo]=s;}
  for(h=0;h<NH;h++)for(t=0;t<T;t++){float sc[1100],mx=-1e30f,sm=0,*o=ao+t*NC+h*D,*q=qkv+t*2304+h*D;
   for(j=0;j<=t;j++){float s=0,*k=qkv+j*2304+768+h*D;for(d=0;d<D;d++)s+=q[d]*k[d];s/=8;sc[j]=s;if(s>mx)mx=s;}
   for(j=0;j<=t;j++){sc[j]=expf(sc[j]-mx);sm+=sc[j];}
   for(d=0;d<D;d++)o[d]=0;
   for(j=0;j<=t;j++){float p=sc[j]/sm,*v=qkv+j*2304+1536+h*D;for(d=0;d<D;d++)o[d]+=p*v[d];}}
  for(t=0;t<T;t++)for(c=0;c<NC;c++){float s=cb[c],*ar=ao+t*NC;for(j=0;j<NC;j++)s+=ar[j]*cw[j*NC+c];x[t*NC+c]+=s;}
  ln(x,a,T,g2,b2);
  for(t=0;t<T;t++)for(fo=0;fo<NF;fo++){float s=fcb[fo],*ar=a+t*NC;for(c=0;c<NC;c++)s+=ar[c]*fcw[c*NF+fo];hh[(size_t)t*NF+fo]=gelu(s);}
  for(t=0;t<T;t++)for(c=0;c<NC;c++){float s=pb[c],*hr=hh+(size_t)t*NF;for(j=0;j<NF;j++)s+=hr[j]*pw[j*NC+c];x[t*NC+c]+=s;}}
 float*xr=x+(T-1)*NC,m=0,v=0,fin[NC];
 for(c=0;c<NC;c++)m+=xr[c];m/=NC;
 for(c=0;c<NC;c++){float e=xr[c]-m;v+=e*e;}v/=NC;
 float is=1/sqrtf(v+1e-5f);for(c=0;c<NC;c++)fin[c]=(xr[c]-m)*is*lnfg[c]+lnfb[c];
 int best=0;float bv=-1e30f;
 for(int vi=0;vi<NV;vi++){float s=0,*w=wte+(size_t)vi*NC;for(c=0;c<NC;c++)s+=fin[c]*w[c];if(s>bv){bv=s;best=vi;}}
 free(x);free(a);free(qkv);free(ao);free(hh);return best;
}
void ptok(int id){char*s=idstr[id];while(*s){int cp;unsigned char c=*s;if(c<0x80){cp=c;s++;}else{cp=((c&0x1F)<<6)|(s[1]&0x3F);s+=2;}putchar(cp2b[cp]);}}
int main(int argc,char**argv){
 voc=mk(1<<17);mrg=mk(1<<16);bytes_init();bpe_init(argv[2]);
 FILE*f=fopen(argv[1],"rb");W=malloc((size_t)124439808*4);fread(W,4,124439808,f);fclose(f);
 wte=W;wpe=wte+(size_t)NV*NC;float*lnf=wpe+1024*NC+(size_t)NL*LSZ;lnfg=lnf;lnfb=lnf+NC;
 pretok(argv[3]);
 for(int step=0;step<20;step++){int nx=forward(nt);toks[nt++]=nx;ptok(nx);}
 putchar('\n');return 0;
}
